def costas_backtrack(n):
    diffs = [set() for _ in range(n)]
    perm = []
    cols = set()

    def backtrack(row):
        if row == n:
            return list(perm)

        for c in range(n):
            if c in cols:
                continue

            # Check if adding c violates Costas property
            valid = True
            for d in range(1, row + 1):
                diff = c - perm[row - d]
                if diff in diffs[d]:
                    valid = False
                    break

            if not valid:
                continue

            # Add c
            perm.append(c)
            cols.add(c)
            for d in range(1, row + 1):
                diffs[d].add(c - perm[row - d])

            res = backtrack(row + 1)
            if res:
                return res

            # Backtrack
            for d in range(1, row + 1):
                diffs[d].remove(c - perm[row - d])
            cols.remove(c)
            perm.pop()

    return backtrack(0)

